@media (min-width: 481px) and (max-width: 767px) {
  /* 旧的中等屏幕内联按钮样式 - 已废弃 */

  /* 中等屏幕顶部按钮样式 */
  .detail-actions-top {
    padding: 16px;
    flex-direction: column;
    gap: 12px;
  }

  .detail-actions-top .detail-btn {
    height: 48px;
    max-width: none;
    width: 100%;
    font-size: 16px;
    font-weight: 600;
    border-radius: 12px;
  }
}

/* 大屏幕桌面端按钮样式 (768px+) */
@media (min-width: 768px) {
  /* 旧的大屏幕内联按钮样式 - 已废弃 */

  /* 大屏幕顶部按钮样式 */
  .detail-actions-top {
    padding: 16px;
    flex-direction: row;
    gap: 16px;
    justify-content: center;
  }

  .detail-actions-top .detail-btn {
    height: 40px;
    max-width: 140px;
    width: auto;
    flex: 1;
    font-size: 15px;
    font-weight: 600;
    border-radius: 20px;
  }
}

/* 响应式设计 - 移动端优先 */

/* 650px以下 - 小屏手机 */
@media (max-width: 650px) {
  /* 容器样式优化 */
  .story-assistant-container {
    padding: 4px;
    border-radius: var(--border-radius-small);
    max-width: 100%;
  }

  .main-interface,
  .story-list-section,
  .story-detail-section,
  .settings-section {
    margin: 0;
    border-radius: var(--border-radius-small);
  }

  /* 导航栏 - 流式布局 */
  .navigation-section {
    padding: 6px 8px;
    min-height: auto;
    gap: 6px;
    flex-wrap: wrap;
    justify-content: center;
  }

  /* 按钮尺寸优化 */
  .nav-btn {
    width: 38px;
    height: 38px;
    font-size: 16px;
    flex-shrink: 0;
  }

  #nextBtn,
  .next-btn {
    width: 48px;
    height: 38px;
    font-size: 16px;
  }

  /* 当前剧情显示区 - 流式布局 */
  .current-story-display {
    flex: 1 1 100%;
    order: -1;
    padding: 8px;
    margin-bottom: 6px;
    min-width: 0;
  }

  .story-title-wrapper {
    width: 100%;
    padding: 4px;
  }

  .story-title {
    font-size: 16px;
    line-height: 1.4;
    word-break: break-word;
  }

  .story-status {
    font-size: 13px;
  }

  .story-progress {
    font-size: 12px;
    padding: 4px 8px;
    margin-top: 4px;
  }

  /* 操作按钮区 */
  .action-buttons {
    gap: 4px;
    flex-shrink: 0;
  }

  .action-btn {
    width: 34px;
    height: 34px;
    font-size: 14px;
  }

  /* 弹出面板优化 */
  .popup-panel.show {
    max-height: 70vh;
  }

  .story-detail-section.popup-panel.show {
    max-height: 75vh;
  }

  /* 列表容器 */
  .story-list-container {
    max-height: 50vh;
    padding: 6px 8px 8px;
  }

  .story-item {
    padding: 10px;
    margin-bottom: 6px;
  }

  .story-item-title {
    font-size: 15px;
    word-break: break-word;
  }

  .story-item-location {
    font-size: 13px;
  }

  /* 详情内容 */
  .detail-content {
    padding: 12px;
    max-height: 65vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    scroll-behavior: smooth;
  }

  .detail-item.compact {
    margin-bottom: 10px;
  }

  .detail-item.compact label {
    font-size: 12px;
  }

  .detail-item.compact div {
    font-size: 14px;
    word-break: break-word;
  }

  /* 步骤列表 */
  .steps-title {
    font-size: 16px;
    margin-bottom: 12px;
  }

  .step-item {
    flex-direction: column;
    gap: 8px;
    padding: 12px;
  }

  .step-header-line {
    width: 100%;
  }

  .step-characters-inline {
    font-size: 13px;
    word-break: break-word;
  }

  .step-event-line {
    font-size: 14px;
    word-break: break-word;
  }

  .step-actions {
    width: 100%;
    justify-content: stretch;
  }

  .step-execute-btn {
    width: 100%;
    padding: 10px;
    font-size: 15px;
    justify-content: center;
  }

  /* 详情顶部按钮 */
  .detail-actions-top {
    padding: 12px;
    flex-direction: column;
    gap: 10px;
  }

  .detail-actions-top .detail-btn {
    height: 44px;
    max-width: none;
    width: 100%;
    font-size: 15px;
    border-radius: 10px;
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
  }

  /* 设置面板 */
  .settings-content {
    padding: 12px;
    max-height: 65vh;
    overflow-y: auto;
  }

  .setting-item {
    margin-bottom: 14px;
    padding-bottom: 10px;
  }

  .setting-item label {
    font-size: 14px;
  }

  .setting-item select {
    font-size: 15px;
    padding: 10px;
  }

  /* 详情布局流式化 */
  .detail-row {
    flex-direction: column;
    gap: 8px;
  }

  .detail-row .detail-item {
    flex: none;
  }

  .detail-item.inline {
    flex-direction: column;
    align-items: flex-start;
  }

  .detail-item.inline label {
    width: auto;
    margin-right: 0;
    margin-bottom: 4px;
  }

  /* 回到当前剧情按钮 */
  .back-to-current-btn {
    width: 30px;
    height: 30px;
    font-size: 13px;
    margin-left: 4px;
  }

  /* 反馈消息 */
  .feedback-message {
    top: 10px;
    padding: 10px 16px;
    font-size: 13px;
    border-radius: 16px;
    max-width: 90%;
  }

  /* 对话框优化 */
  .confirmation-dialog {
    width: 92%;
    max-width: 320px;
  }

  .dialog-title {
    font-size: 15px;
  }

  .dialog-message {
    font-size: 14px;
  }

  .dialog-btn {
    padding: 12px;
    font-size: 15px;
  }
}

/* 481px-650px - 中等屏幕 */
@media (min-width: 481px) and (max-width: 650px) {
  .navigation-section {
    padding: 8px 12px;
    gap: 8px;
  }

  .nav-btn {
    width: 42px;
    height: 42px;
  }

  #nextBtn,
  .next-btn {
    width: 52px;
    height: 42px;
  }

  .story-title {
    font-size: 18px;
  }

  .action-btn {
    width: 38px;
    height: 38px;
  }

  .detail-actions-top {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 12px;
  }

  .detail-actions-top .detail-btn {
    flex: 1 1 calc(50% - 6px);
    min-width: 120px;
    height: 42px;
  }
}

/* 480px以下 - 超小屏 */
@media (max-width: 480px) {
  .story-assistant-container {
    padding: 3px;
  }

  .navigation-section {
    padding: 6px;
  }

  .nav-btn {
    width: 36px;
    height: 36px;
    font-size: 15px;
  }

  #nextBtn,
  .next-btn {
    width: 46px;
    height: 36px;
  }

  .current-story-display {
    padding: 6px;
  }

  .story-title {
    font-size: 15px;
  }

  .story-status {
    font-size: 12px;
  }

  .action-btn {
    width: 32px;
    height: 32px;
    font-size: 13px;
  }

  .story-item {
    padding: 8px;
  }

  .detail-content {
    padding: 10px;
  }

  .step-item {
    padding: 10px;
  }

  .detail-actions-top {
    padding: 10px;
  }

  .detail-actions-top .detail-btn {
    height: 42px;
    font-size: 14px;
  }
}

/* 滚动条美化 - iPhone风格 */
.story-list-container::-webkit-scrollbar,
.detail-content::-webkit-scrollbar {
  width: 4px;
}

.story-list-container::-webkit-scrollbar-track,
.detail-content::-webkit-scrollbar-track {
  background: transparent;
}

.story-list-container::-webkit-scrollbar-thumb,
.detail-content::-webkit-scrollbar-thumb {
  background: rgba(120, 120, 128, 0.3);
  border-radius: 2px;
}

.story-list-container::-webkit-scrollbar-thumb:hover,
.detail-content::-webkit-scrollbar-thumb:hover {
  background: rgba(120, 120, 128, 0.5);
}

/* 动画增强 */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 弹出面板动画 - 从下方向上滑入 */
@keyframes popupSlideUp {
  from {
    opacity: 0;
    transform: translateY(20px) scaleY(0.8);
    max-height: 0;
  }
  to {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: calc(100vh - 80px);
  }
}

/* 弹出面板隐藏动画 - 向下滑出 */
@keyframes popupSlideDown {
  from {
    opacity: 1;
    transform: translateY(0) scaleY(1);
    max-height: calc(100vh - 80px);
  }
  to {
    opacity: 0;
    transform: translateY(20px) scaleY(0.8);
    max-height: 0;
  }
}

.main-interface {
  animation: fadeInUp 0.5s ease-out;
}

/* 无障碍支持 */
.control-btn:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

.story-item:focus {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* 剧情详情样式 */
.story-info-section {
  margin-bottom: 16px;
  background: linear-gradient(135deg, rgba(0, 122, 255, 0.05) 0%, rgba(88, 86, 214, 0.05) 100%);
  border-radius: var(--border-radius-small);
  padding: 12px 14px;
  border: 1px solid rgba(0, 122, 255, 0.1);
}

/* 返回列表按钮样式 */
.back-to-list-btn {
  width: 32px;
  height: 32px;
  border: none;
  background: rgba(120, 120, 128, 0.2);
  border-radius: 16px;
  color: var(--text-primary);
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  margin-right: 8px;
}

.back-to-list-btn:hover {
  background: rgba(120, 120, 128, 0.3);
  transform: scale(1.05);
}

/* 压缩的详情项样式 */
.detail-item {
  margin-bottom: 0;
  padding: 0;
  border-bottom: none;
}

.detail-item + .detail-item {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(0, 122, 255, 0.1);
}

.detail-item.compact {
  margin-bottom: 0;
  padding-bottom: 0;
}

.detail-item.compact label {
  display: none;
}

.detail-item.compact div {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.5;
  font-weight: 400;
}

.detail-item.compact div strong {
  color: var(--primary-color);
  font-weight: 700;
  margin-right: 6px;
}

.steps-section {
  margin-top: 20px;
}

.steps-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 16px;
  padding-left: 12px;
  border-left: 3px solid var(--primary-color);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.steps-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* 步骤项样式 */
/* 步骤项 - 全新卡片式设计 */
.step-item {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 0;
  background: var(--surface-color);
  border-radius: 12px;
  border: 2px solid #e8e8ed;
  overflow: hidden;
  transition: var(--transition);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-item:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  border-color: var(--primary-color);
}

.step-item.executed {
  border-color: var(--success-color);
}

.step-item.pending {
  border-color: #a99de8;
}

/* 步骤头部 - 紧凑设计 */
.step-header-line {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
  border-bottom: 1px solid #e8e8ed;
}

.step-item.executed .step-header-line {
  background: linear-gradient(135deg, rgba(52, 199, 89, 0.1) 0%, rgba(52, 199, 89, 0.05) 100%);
}

.step-item.pending .step-header-line {
  background: linear-gradient(135deg, rgba(139, 127, 214, 0.1) 0%, rgba(139, 127, 214, 0.05) 100%);
}

.step-id {
  font-size: 11px;
  font-weight: 700;
  color: var(--primary-color);
  background: rgba(0, 122, 255, 0.1);
  padding: 4px 10px;
  border-radius: 12px;
  white-space: nowrap;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.step-item.executed .step-id {
  color: var(--success-color);
  background: rgba(52, 199, 89, 0.15);
}

.step-item.pending .step-id {
  color: #8b7fd6;
  background: rgba(139, 127, 214, 0.15);
}

/* 步骤内容区 */
.step-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 12px;
}

/* 步骤地点字段 */
.step-location-field {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
}

.location-label {
  font-size: 14px;
  flex-shrink: 0;
}

.step-location-input {
  flex: 1;
  padding: 4px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  transition: var(--transition);
  min-width: 100px;
}

.step-location-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(0, 122, 255, 0.1);
}

/* 紧凑字段容器 */
.step-field-compact {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* 内联标签 */
.inline-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-secondary);
  display: inline-block;
}

/* 角色编辑器 */
.characters-editor {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.character-item {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 8px;
  background: rgba(88, 86, 214, 0.03);
  border-radius: 6px;
  border: 1px solid rgba(88, 86, 214, 0.1);
}

/* 角色字段 */
.char-field {
  display: flex;
  align-items: center;
  gap: 6px;
}

.char-field.full-width {
  grid-column: 1 / 3;
}

.char-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--secondary-color);
  white-space: nowrap;
  flex-shrink: 0;
}

.char-name-input,
.char-mood-input,
.char-thoughts-input {
  flex: 1;
  padding: 5px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 5px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  transition: var(--transition);
}

.char-name-input {
  font-weight: 600;
}

.char-name-input:focus,
.char-mood-input:focus,
.char-thoughts-input:focus {
  outline: none;
  border-color: var(--secondary-color);
  box-shadow: 0 0 0 2px rgba(88, 86, 214, 0.1);
}

.no-characters {
  padding: 12px;
  text-align: center;
  color: var(--text-secondary);
  font-size: 12px;
  font-style: italic;
}

/* 事件描述输入 - 2行textarea */
.step-event-input {
  padding: 6px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  resize: vertical;
  font-family: inherit;
  line-height: 1.5;
  transition: var(--transition);
  width: 100%;
}

.step-event-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(0, 122, 255, 0.1);
}

/* 剧情发展输入 - 单行input */
.step-development-input {
  padding: 5px 10px;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  font-size: 12px;
  color: var(--text-primary);
  background: var(--surface-color);
  transition: var(--transition);
  width: 100%;
}

.step-development-input:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(0, 122, 255, 0.1);
}

.step-execute-btn {
  padding: 6px 14px;
  border: none;
  border-radius: 16px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  min-width: auto;
  white-space: nowrap;
}

.step-execute-btn .btn-icon {
  font-size: 14px;
}

.step-execute-btn.pending {
  background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);
  color: white;
  box-shadow: 0 2px 8px rgba(0, 122, 255, 0.3);
}

.step-execute-btn.pending:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 122, 255, 0.4);
}

.step-execute-btn.executed {
  background: linear-gradient(135deg, var(--success-color) 0%, #28a745 100%);
  color: white;
  box-shadow: 0 2px 8px rgba(52, 199, 89, 0.3);
}

.step-execute-btn.executed:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(52, 199, 89, 0.4);
}

.step-execute-btn:active {
  transform: translateY(0);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
}

/* 主题特定增强样式 */

/* 女性化可爱系主题增强 */
[data-theme='cute'] .story-assistant-container {
  background: var(--accent-gradient);
  border: 2px solid rgba(255, 107, 157, 0.3);
}

[data-theme='cute'] .nav-btn,
[data-theme='cute'] .action-btn {
  background: linear-gradient(145deg, rgba(255, 192, 203, 0.3), rgba(255, 182, 193, 0.2));
  border: 1px solid rgba(255, 107, 157, 0.2);
}

[data-theme='cute'] .nav-btn:hover:not(:disabled) {
  background: var(--accent-gradient);
  box-shadow: 0 4px 15px rgba(255, 107, 157, 0.4);
  transform: scale(var(--button-hover-scale)) rotate(2deg);
}

[data-theme='cute'] .story-progress {
  background: linear-gradient(45deg, rgba(255, 107, 157, 0.1), rgba(255, 140, 200, 0.1));
  border-left: 3px solid var(--primary-color);
  box-shadow: 0 2px 10px rgba(255, 107, 157, 0.2);
}

[data-theme='cute'] .confirmation-dialog {
  background: linear-gradient(145deg, #ffffff, #fef7f7);
  border: 2px solid rgba(255, 107, 157, 0.3);
}

/* 轻奢主题增强 */
[data-theme='luxury'] .story-assistant-container {
  background: var(--accent-gradient);
  border: 2px solid rgba(212, 175, 55, 0.4);
  box-shadow: 0 12px 40px rgba(212, 175, 55, 0.2), 0 4px 12px rgba(0, 0, 0, 0.1);
}

[data-theme='luxury'] .nav-btn,
[data-theme='luxury'] .action-btn {
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(244, 228, 188, 0.3));
  border: 1px solid rgba(212, 175, 55, 0.3);
  box-shadow: 0 2px 8px rgba(212, 175, 55, 0.15);
}

[data-theme='luxury'] .nav-btn:hover:not(:disabled) {
  background: linear-gradient(145deg, #d4af37, #f4e4bc);
  color: #2d2926;
  box-shadow: 0 6px 20px rgba(212, 175, 55, 0.4);
  transform: scale(var(--button-hover-scale));
}

[data-theme='luxury'] .story-progress {
  background: linear-gradient(45deg, rgba(212, 175, 55, 0.1), rgba(244, 228, 188, 0.2));
  border-left: 4px solid var(--primary-color);
  box-shadow: 0 4px 15px rgba(212, 175, 55, 0.25);
  backdrop-filter: blur(10px);
}

[data-theme='luxury'] .confirmation-dialog {
  background: linear-gradient(145deg, #ffffff, #faf9f7);
  border: 2px solid rgba(212, 175, 55, 0.4);
  box-shadow: 0 20px 60px rgba(212, 175, 55, 0.3);
}

[data-theme='luxury'] .feedback-message {
  background: linear-gradient(135deg, #d4af37, #b8860b);
  box-shadow: 0 8px 25px rgba(212, 175, 55, 0.4);
  color: #ffffff;
  font-weight: 600;
}

/* 轻奢主题特殊装饰效果 */
[data-theme='luxury'] .story-title {
  background: linear-gradient(135deg, #d4af37, #b8860b);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(212, 175, 55, 0.3);
}

[data-theme='luxury'] .story-assistant-container {
  position: relative;
  overflow: hidden;
}

[data-theme='luxury'] .story-assistant-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, #d4af37, transparent);
  opacity: 0.6;
}

[data-theme='luxury'] .navigation-section {
  position: relative;
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(212, 175, 55, 0.2);
}

[data-theme='luxury'] .navigation-section::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 60%;
