  /**
   * 构建要发送的步骤对象（从用户输入读取）
   */
  function buildStepObject(story, step) {
    const stepId = step.stepId;

    // 从页面输入框读取用户编辑的值
    const $stepItem = $(`.step-item[data-step-id="${stepId}"]`);

    // 读取地点
    const location = $stepItem.find('.step-location-input').val() || step.location || '未指定';

    // 读取角色信息
    let charactersData = [];
    if (step.characters && Array.isArray(step.characters)) {
      charactersData = step.characters.map((char, charIndex) => {
        const name = $stepItem.find(`.char-name-input[data-char-index="${charIndex}"]`).val() || char.name || '';
        const mood = $stepItem.find(`.char-mood-input[data-char-index="${charIndex}"]`).val() || char.mood || '';
        const innerThoughts =
          $stepItem.find(`.char-thoughts-input[data-char-index="${charIndex}"]`).val() || char.innerThoughts || '';

        return {
          name: name,
          mood: mood,
          innerThoughts: innerThoughts,
        };
      });
    }

    // 读取事件描述
    const event = $stepItem.find('.step-event-input').val() || step.event || '';

    // 读取剧情发展
    const development = $stepItem.find('.step-development-input').val() || step.development || '';

    return {
      location: location,
      characters: charactersData,
      event: event,
      development: development,
    };
  }

